def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row},
             key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]
    marks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    color = 3

    # Lines through marker pairs sharing a row or column.
    rows, cols = {}, {}
    for r, c in marks:
        rows.setdefault(r, []).append(c)
        cols.setdefault(c, []).append(r)

    hsegs, vsegs = [], []
    for r, cs in rows.items():
        if len(cs) >= 2:
            a, b = min(cs), max(cs)
            hsegs.append((r, a, b))
            for c in range(a, b + 1):
                if out[r][c] == bg:
                    out[r][c] = color
    for c, rs in cols.items():
        if len(rs) >= 2:
            a, b = min(rs), max(rs)
            vsegs.append((c, a, b))
            for r in range(a, b + 1):
                if out[r][c] == bg:
                    out[r][c] = color

    # Join aligned endpoints of parallel marker-pair segments.
    for i, (r1, a1, b1) in enumerate(hsegs):
        for r2, a2, b2 in hsegs[i + 1:]:
            for c in {a1, b1} & {a2, b2}:
                for r in range(min(r1, r2), max(r1, r2) + 1):
                    if out[r][c] == bg:
                        out[r][c] = color

    for i, (c1, a1, b1) in enumerate(vsegs):
        for c2, a2, b2 in vsegs[i + 1:]:
            for r in {a1, b1} & {a2, b2}:
                for c in range(min(c1, c2), max(c1, c2) + 1):
                    if out[r][c] == bg:
                        out[r][c] = color
    return out
